# /opt/zeek/share/zeek/site/dns-exfil-detect.zeek
@load base/protocols/dns

module DNSExfil;

# Track query counts per source per base domain
global query_counts: table[addr, string] of count &default=0 &create_expire=1hr;

function get_base_domain(fqdn: string): string {
  local labels = split_string(fqdn, /\./);
  if (|labels| >= 2)
    return labels[|labels|-2] + "." + labels[|labels|-1];
  return fqdn;
}

function label_entropy(s: string): double {
  local freq: table[string] of count &default=0;
  for (i in s) freq[s[i]] += 1;
  local entropy = 0.0;
  for (c in freq) {
    local p = freq[c] / (1.0 * |s|);
    entropy -= p * log(p) / log(2.0);
  }
  return entropy;
}

event dns_request(c: connection, msg: dns_msg, query: string, qtype: count, qclass: count) {
  # Flag NULL record queries (iodine)
  if (qtype == 10) {
    NOTICE([$note=Weird::Activity, $conn=c,
            $msg=fmt("DNS NULL record query: %s from %s", query, c$id$orig_h)]);
  }
  # Check label length
  local labels = split_string(query, /\./);
  for (lbl in labels) {
    if (|labels[lbl]| > 50) {
      NOTICE([$note=Weird::Activity, $conn=c,
              $msg=fmt("Long DNS label (%d chars): %s", |labels[lbl]|, query)]);
    }
    if (|labels[lbl]| > 15 && label_entropy(labels[lbl]) > 3.5) {
      NOTICE([$note=Weird::Activity, $conn=c,
              $msg=fmt("High-entropy DNS label (%.2f): %s", label_entropy(labels[lbl]), query)]);
    }
  }
  # Track volume
  local base = get_base_domain(query);
  query_counts[c$id$orig_h, base] += 1;
  if (query_counts[c$id$orig_h, base] == 500) {
    NOTICE([$note=Weird::Activity, $conn=c,
            $msg=fmt("High DNS volume: %s → %s (500+ queries/hr)",
                     c$id$orig_h, base)]);
  }
}

#!/usr/bin/env python3
# dns_entropy_hunt.py — analyse DNS query log for exfil patterns
import math, re, sys
from collections import Counter

def shannon_entropy(s):
    if not s: return 0
    freq = Counter(s.lower())
    length = len(s)
    return -sum((c/length)*math.log2(c/length) for c in freq.values())

def analyse_query(fqdn):
    alerts = []
    labels = fqdn.rstrip('.').split('.')
    if len(labels) < 2: return []
    # Skip TLD and second-level domain
    subdomain_labels = labels[:-2]
    for lbl in subdomain_labels:
        if len(lbl) > 50:
            alerts.append(f'LONG_LABEL({len(lbl)}): {lbl}')
        ent = shannon_entropy(lbl)
        if len(lbl) > 15 and ent > 3.5:
            alerts.append(f'HIGH_ENTROPY({ent:.2f}): {lbl}')
        # Base32 pattern (A-Z2-7 only)
        if re.match(r'^[A-Z2-7]{20,}$', lbl.upper()):
            alerts.append(f'BASE32_PATTERN: {lbl}')
        # Hex pattern
        if re.match(r'^[0-9a-f]{30,}$', lbl.lower()):
            alerts.append(f'HEX_PATTERN: {lbl}')
    return alerts

# Read from Zeek dns.log or any newline-separated FQDN list
for line in sys.stdin:
    fqdn = line.strip()
    alerts = analyse_query(fqdn)
    if alerts:
        print(f'[ALERT] {fqdn}')
        for a in alerts: print(f'  → {a}')

